/** 第二名赛事干事确认相同建议（原子重算榜单）或驳回。 */
ServiceResult confirmAppeal(String raceId, String appealKey, ConfirmAppealRequest request);

/** 查询赛事全部申诉证据，只读、稳定排序。 */
