        if (runner.finishTimeMs() == null) throw new UnprocessableEntityException("选手尚无完赛耗时，不在申诉窗口内");
        long now = clock.millis();
        if (now > runner.updatedAt() + APPEAL_WINDOW_MS) throw new UnprocessableEntityException("申诉窗口已截止：finishAt后30分钟内");
        // 未申诉约束由 uk_appeal_penalty 兜底，但先友好检查
        // freeze: compute current standings
        List<RunnerRow> runners = repository.findRunners(raceId);
        List<PenaltyRow> penalties = repository.findPenalties(raceId);
        List<CheckpointRow> checkpoints = repository.findCheckpoints(raceId);
        List<CheckpointTimingRow> timings = repository.findAllTimings(raceId);
        List<ResultEntry> entries = ResultCalculator.compute(...);
        ResultEntry own = entries.stream().filter(e -> e.bib().equals(bib)).findFirst().orElseThrow();
        // frozen segments
        List<AppealResponse.Segment> segments = ... build from checkpoints + timings for this bib
        String frozenSegmentsJson = writeJson(segments);
        AppealRow row = new AppealRow(... status PENDING, penaltyVersion, frozen..., leaderboardVersion = race.version(), createdAt=now ...);
        try { repository.insertAppeal(row); } catch (DuplicateKeyException ex) {
            if (constraintMatches(ex, "uk_appeal_penalty") || message contains penalty_id) throw new ConflictException("该处罚已存在申诉");
            throw new ConflictException("appealKey已存在: " + ...);
        }
        return ServiceResult.created(toAppealResponse(repository.findAppeal(key).orElseThrow()));
