 * 测试可注入 {@link MutableClock} 推进时间以覆盖申诉窗口边界。
 */
@TestConfiguration
public class MutableClockTestConfig {

    @Bean
    @Primary
    public MutableClock mutableClock() {
        return new MutableClock(FixedClockTestConfig.FIXED_INSTANT);
    }
}

