        AppealResponse recommended = recommend("ak-1", "off-1", "UPHOLD", null, "req-r1");
        assertThat(recommended.status()).isEqualTo(AppealStatus.PENDING);
        assertThat(recommended.firstOpinion().officialId()).isEqualTo("off-1");
